WITH enriched AS (SELECT id, account_id, txn_type, amount, txn_time, merchant, is_flagged, FIRST_VALUE(merchant) IGNORE NULLS OVER (PARTITION BY txn_type, account_id ORDER BY txn_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_merchant, LEAD(amount, 1) OVER (ORDER BY txn_time, id) AS next_amount, COUNT(amount) OVER (ORDER BY CAST(txn_time AS BIGINT) RANGE BETWEEN 604800 PRECEDING AND CURRENT ROW) AS amount_count_7d, RANK() OVER (PARTITION BY account_id ORDER BY amount NULLS LAST) AS amount_rank, SUM(amount) OVER (PARTITION BY account_id ORDER BY amount, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_amount FROM transactions), with_gaps AS (SELECT *, CASE WHEN LAG(txn_time) OVER (PARTITION BY txn_type ORDER BY txn_time, id) IS NULL OR txn_time > LAG(txn_time) OVER (PARTITION BY txn_type ORDER BY txn_time, id) + INTERVAL '90' DAY THEN 1 ELSE 0 END AS new_group_flag FROM enriched), sessions_transactions AS (SELECT *, SUM(new_group_flag) OVER (PARTITION BY txn_type ORDER BY txn_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS burst_id FROM with_gaps), flagged AS (SELECT *, CASE WHEN LAG(txn_time) OVER (PARTITION BY merchant ORDER BY txn_time, id) IS NULL OR txn_time > LAG(txn_time) OVER (PARTITION BY merchant ORDER BY txn_time, id) + INTERVAL 30 DAYS THEN 1 ELSE 0 END AS is_new_burst FROM sessions_transactions), islands AS (SELECT *, SUM(is_new_burst) OVER (PARTITION BY merchant ORDER BY txn_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS burst_id_2 FROM flagged) SELECT DATE_TRUNC('WEEK', txn_time) AS week_start, CASE WHEN burst_id >= 7 THEN 'PREMIUM' ELSE 'STANDARD' END AS burst_id_tier, (UNIX_TIMESTAMP(MAX(txn_time)) - UNIX_TIMESTAMP(MIN(txn_time))) / 60 AS span_minutes, ROUND(AVG(next_amount), 2) AS avg_next_amount, SORT_ARRAY(COLLECT_SET(merchant)) AS merchant_list, SIZE(COLLECT_SET(txn_type)) AS num_txn_types, PERCENT_RANK() OVER (PARTITION BY DATE_TRUNC('WEEK', txn_time) ORDER BY ROUND(AVG(next_amount), 2) DESC) AS avg_next_amount_percent_rank FROM islands GROUP BY DATE_TRUNC('WEEK', txn_time), CASE WHEN burst_id >= 7 THEN 'PREMIUM' ELSE 'STANDARD' END;
